"""Parse Square's "Item details" CSV export into sale rows.

Square Dashboard -> Reports -> Items -> Export -> "Item Detail CSV".
Column names are matched case-insensitively so minor export differences are fine.
"""

import csv
import datetime as dt
import hashlib
import io
import re
from collections import Counter
from decimal import Decimal, InvalidOperation


class SquareImportError(Exception):
    pass


REQUIRED_COLUMNS = ["Date", "Item", "Qty", "Net Sales"]


def parse_money(value):
    """'$5.50' -> 550, '($1.00)' or '-$1.00' -> -100, '' -> 0."""
    s = (value or "").strip()
    if not s:
        return 0
    negative = s.startswith("-") or (s.startswith("(") and s.endswith(")"))
    digits = re.sub(r"[^0-9.]", "", s)
    if not digits:
        return 0
    try:
        cents = int((Decimal(digits) * 100).quantize(Decimal("1")))
    except InvalidOperation:
        raise SquareImportError(f"Couldn't read the amount {value!r}")
    return -cents if negative else cents


def parse_date(value):
    s = (value or "").strip()
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m/%d/%y"):
        try:
            return dt.datetime.strptime(s, fmt).date().isoformat()
        except ValueError:
            pass
    raise SquareImportError(f"Couldn't read the date {value!r}")


def parse_qty(value):
    s = (value or "").strip().replace(",", "")
    if not s:
        return 0.0
    try:
        return float(s)
    except ValueError:
        raise SquareImportError(f"Couldn't read the quantity {value!r}")


def split_modifiers(value):
    return [m.strip() for m in (value or "").split(",") if m.strip()]


def parse_square_csv(data: bytes):
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        text = data.decode("latin-1")

    reader = csv.DictReader(io.StringIO(text))
    headers = {h.strip().lower(): h for h in (reader.fieldnames or []) if h}
    missing = [c for c in REQUIRED_COLUMNS if c.lower() not in headers]
    if missing:
        raise SquareImportError(
            "This doesn't look like a Square Item Detail export "
            f"(missing columns: {', '.join(missing)})."
        )

    def col(row, name):
        h = headers.get(name.lower())
        return (row.get(h) or "").strip() if h else ""

    rows = []
    seen = Counter()
    for line_no, row in enumerate(reader, start=2):
        if not col(row, "Item") and not col(row, "Date"):
            continue
        try:
            net = parse_money(col(row, "Net Sales"))
            r = {
                "date": parse_date(col(row, "Date")),
                "time": col(row, "Time"),
                "category": col(row, "Category"),
                "item": col(row, "Item"),
                "variation": col(row, "Price Point Name"),
                "modifiers": ", ".join(split_modifiers(col(row, "Modifiers Applied"))),
                "qty": parse_qty(col(row, "Qty")),
                "gross_cents": parse_money(col(row, "Gross Sales")) if "gross sales" in headers else net,
                "discount_cents": parse_money(col(row, "Discounts")),
                "net_cents": net,
                "tax_cents": parse_money(col(row, "Tax")),
                "event_type": col(row, "Event Type") or "Payment",
                "transaction_id": col(row, "Transaction ID"),
            }
        except SquareImportError as e:
            raise SquareImportError(f"Row {line_no}: {e}")

        # Identical lines in one transaction are legitimate (two of the same
        # drink), so the key includes how many times we've seen this line.
        fingerprint = "|".join(
            str(r[k]) for k in ("date", "time", "item", "variation", "modifiers",
                                "qty", "net_cents", "event_type", "transaction_id")
        )
        seen[fingerprint] += 1
        r["import_key"] = hashlib.sha1(
            f"{fingerprint}#{seen[fingerprint]}".encode()
        ).hexdigest()
        rows.append(r)
    return rows

