import datetime as dt
import os
import sqlite3
from collections import Counter, defaultdict

from flask import Flask, flash, g, redirect, render_template, request, url_for

from square_import import SquareImportError, parse_square_csv, split_modifiers

app = Flask(__name__)
app.config["DATABASE"] = os.environ.get("BOBA_DB", os.path.join(app.root_path, "boba.db"))
app.config["MAX_CONTENT_LENGTH"] = 20 * 1024 * 1024
app.secret_key = os.environ.get("BOBA_SECRET", "local-only")

EXPENSE_CATEGORIES = [
    "Ingredients", "Packaging", "Rent", "Utilities", "Payroll",
    "Equipment", "Card & POS fees", "Marketing", "Insurance", "Other",
]


# ---------- database ----------

def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(app.config["DATABASE"])
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    with app.app_context():
        with open(os.path.join(app.root_path, "schema.sql")) as f:
            get_db().executescript(f.read())


init_db()


# ---------- helpers ----------

@app.template_filter("money")
def money(cents):
    cents = round(cents or 0)
    sign = "-" if cents < 0 else ""
    return f"{sign}${abs(cents) / 100:,.2f}"


@app.template_filter("num")
def num(value):
    value = value or 0
    return f"{value:,.0f}" if float(value).is_integer() else f"{value:,.2f}"


def today():
    return dt.date.today()


def parse_amount(value):
    """'12.50' or '$1,200' -> cents."""
    s = (value or "").replace("$", "").replace(",", "").strip()
    return round(float(s) * 100)


def date_range():
    """Read ?start=&end= from the query string; default to this month."""
    t = today()
    start = request.args.get("start") or t.replace(day=1).isoformat()
    end = request.args.get("end") or t.isoformat()
    if start > end:
        start, end = end, start
    first_this = t.replace(day=1)
    last_month_end = first_this - dt.timedelta(days=1)
    presets = {
        "This month": (first_this.isoformat(), t.isoformat()),
        "Last month": (last_month_end.replace(day=1).isoformat(), last_month_end.isoformat()),
        "Last 7 days": ((t - dt.timedelta(days=6)).isoformat(), t.isoformat()),
        "This year": (t.replace(month=1, day=1).isoformat(), t.isoformat()),
    }
    return start, end, presets


def stock_levels(db):
    return db.execute(
        """
        SELECT i.*,
               COALESCE((SELECT SUM(qty) FROM stock_movements m WHERE m.ingredient_id = i.id), 0) AS stock,
               COALESCE((SELECT -SUM(qty) FROM stock_movements m
                         WHERE m.ingredient_id = i.id AND m.reason = 'sale' AND m.date >= ?), 0) AS used_30d
        FROM ingredients i ORDER BY i.name COLLATE NOCASE
        """,
        ((today() - dt.timedelta(days=29)).isoformat(),),
    ).fetchall()


def load_recipes(db):
    recipes = defaultdict(list)
    for r in db.execute("SELECT kind, name, ingredient_id, qty FROM recipe_lines"):
        recipes[(r["kind"], r["name"].lower())].append((r["ingredient_id"], r["qty"]))
    return recipes


def item_recipe(recipes, item, variation):
    if variation:
        lines = recipes.get(("item", f"{item} ({variation})".lower()))
        if lines:
            return lines
    return recipes.get(("item", item.lower()), [])


# ---------- dashboard ----------

@app.route("/")
def dashboard():
    db = get_db()
    start, end, presets = date_range()
    rng = (start, end)

    s = db.execute(
        """SELECT COALESCE(SUM(gross_cents),0) gross, COALESCE(SUM(discount_cents),0) discounts,
                  COALESCE(SUM(net_cents),0) net, COALESCE(SUM(tax_cents),0) tax,
                  COALESCE(SUM(CASE WHEN qty > 0 THEN qty END),0) items,
                  COUNT(DISTINCT transaction_id) orders
           FROM sales WHERE date BETWEEN ? AND ?""", rng).fetchone()
    exp_total = db.execute(
        "SELECT COALESCE(SUM(amount_cents),0) FROM expenses WHERE date BETWEEN ? AND ?", rng
    ).fetchone()[0]
    exp_by_cat = db.execute(
        """SELECT category, SUM(amount_cents) total FROM expenses
           WHERE date BETWEEN ? AND ? GROUP BY category ORDER BY total DESC""", rng).fetchall()
    ingredient_cost = db.execute(
        """SELECT COALESCE(SUM(-m.qty * i.cost_per_unit_cents),0)
           FROM stock_movements m JOIN ingredients i ON i.id = m.ingredient_id
           WHERE m.reason = 'sale' AND m.date BETWEEN ? AND ?""", rng).fetchone()[0]

    daily = db.execute(
        """SELECT date, SUM(net_cents) net FROM sales
           WHERE date BETWEEN ? AND ? GROUP BY date ORDER BY date""", rng).fetchall()
    max_day = max([d["net"] for d in daily] + [1])

    top_items = db.execute(
        """SELECT item, SUM(qty) qty, SUM(net_cents) net FROM sales
           WHERE date BETWEEN ? AND ? GROUP BY item ORDER BY qty DESC LIMIT 8""", rng).fetchall()

    low_stock = [i for i in stock_levels(db)
                 if i["reorder_level"] > 0 and i["stock"] <= i["reorder_level"]]

    return render_template(
        "dashboard.html", start=start, end=end, presets=presets, s=s,
        exp_total=exp_total, exp_by_cat=exp_by_cat, ingredient_cost=ingredient_cost,
        profit=s["net"] - exp_total, daily=daily, max_day=max_day,
        top_items=top_items, low_stock=low_stock,
    )


# ---------- sales ----------

@app.route("/sales")
def sales():
    db = get_db()
    start, end, presets = date_range()
    days = db.execute(
        """SELECT date, SUM(CASE WHEN qty > 0 THEN qty END) items,
                  COUNT(DISTINCT transaction_id) orders, SUM(gross_cents) gross,
                  SUM(discount_cents) discounts, SUM(net_cents) net, SUM(tax_cents) tax
           FROM sales WHERE date BETWEEN ? AND ? GROUP BY date ORDER BY date DESC""",
        (start, end)).fetchall()
    day = request.args.get("day")
    lines = []
    if day:
        lines = db.execute("SELECT * FROM sales WHERE date = ? ORDER BY time, id", (day,)).fetchall()
    return render_template("sales.html", start=start, end=end, presets=presets,
                           days=days, day=day, lines=lines)


@app.route("/sales/import", methods=["GET", "POST"])
def import_sales():
    if request.method == "GET":
        return render_template("import.html", result=None)

    f = request.files.get("file")
    if not f or not f.filename:
        flash("Choose a CSV file to upload.", "error")
        return redirect(url_for("import_sales"))
    try:
        rows = parse_square_csv(f.read())
    except SquareImportError as e:
        flash(str(e), "error")
        return redirect(url_for("import_sales"))

    db = get_db()
    recipes = load_recipes(db)
    now = dt.datetime.now().isoformat(timespec="seconds")
    added = duplicates = 0
    no_recipe = Counter()
    dates = []

    for r in rows:
        cur = db.execute(
            """INSERT OR IGNORE INTO sales
               (date, time, category, item, variation, modifiers, qty, gross_cents,
                discount_cents, net_cents, tax_cents, event_type, transaction_id,
                import_key, imported_at)
               VALUES (:date, :time, :category, :item, :variation, :modifiers, :qty,
                       :gross_cents, :discount_cents, :net_cents, :tax_cents, :event_type,
                       :transaction_id, :import_key, :imported_at)""",
            {**r, "imported_at": now})
        if cur.rowcount == 0:
            duplicates += 1
            continue
        added += 1
        dates.append(r["date"])

        # Refunded drinks were still made, so refunds don't put stock back.
        if r["qty"] <= 0:
            continue
        usage = defaultdict(float)
        lines = item_recipe(recipes, r["item"], r["variation"])
        if not lines:
            no_recipe[r["item"]] += r["qty"]
        for ing_id, q in lines:
            usage[ing_id] += q * r["qty"]
        for mod in split_modifiers(r["modifiers"]):
            for ing_id, q in recipes.get(("modifier", mod.lower()), []):
                usage[ing_id] += q * r["qty"]
        db.executemany(
            """INSERT INTO stock_movements (date, ingredient_id, qty, reason, sale_id)
               VALUES (?, ?, ?, 'sale', ?)""",
            [(r["date"], ing_id, -q, cur.lastrowid) for ing_id, q in usage.items()])
    db.commit()

    result = {
        "filename": f.filename, "added": added, "duplicates": duplicates,
        "first": min(dates) if dates else None, "last": max(dates) if dates else None,
        "no_recipe": no_recipe.most_common(),
    }
    return render_template("import.html", result=result)


# ---------- expenses ----------

@app.route("/expenses", methods=["GET", "POST"])
def expenses():
    db = get_db()
    if request.method == "POST":
        form = request.form
        try:
            amount = parse_amount(form["amount"])
            ing_id = int(form["ingredient_id"]) if form.get("ingredient_id") else None
            ing_qty = float(form["ingredient_qty"]) if form.get("ingredient_qty") else None
        except ValueError:
            flash("Amount and quantity need to be numbers.", "error")
            return redirect(url_for("expenses"))
        if ing_id and not ing_qty:
            flash("Enter how much of the ingredient you bought.", "error")
            return redirect(url_for("expenses"))

        cur = db.execute(
            """INSERT INTO expenses (date, vendor, category, description, amount_cents)
               VALUES (?, ?, ?, ?, ?)""",
            (form["date"], form.get("vendor", "").strip(), form["category"],
             form.get("description", "").strip(), amount))
        if ing_id and ing_qty:
            db.execute(
                """INSERT INTO stock_movements (date, ingredient_id, qty, reason, expense_id)
                   VALUES (?, ?, ?, 'purchase', ?)""",
                (form["date"], ing_id, ing_qty, cur.lastrowid))
            # Latest purchase price becomes the ingredient's cost.
