        except ValueError:
            flash("Amount needs to be a number.", "error")
            return redirect(url_for("recipes"))
        db.execute(
            """INSERT INTO recipe_lines (kind, name, ingredient_id, qty) VALUES (?, ?, ?, ?)
               ON CONFLICT (kind, name, ingredient_id) DO UPDATE SET qty = excluded.qty""",
            (form["kind"], form["name"].strip(), int(form["ingredient_id"]), qty))
        db.commit()
        flash("Recipe saved.", "ok")
        return redirect(url_for("recipes") + "#r-" + form["kind"] + "-" + form["name"].strip())

    lines = db.execute(
        """SELECT r.*, i.name ingredient, i.unit, i.cost_per_unit_cents
           FROM recipe_lines r JOIN ingredients i ON i.id = r.ingredient_id
           ORDER BY r.kind, r.name COLLATE NOCASE, i.name COLLATE NOCASE""").fetchall()

    # Average selling price per unit, keyed the same way recipes are matched.
    prices = {}
    agg = defaultdict(lambda: [0.0, 0])
    for s in db.execute(
            """SELECT item, variation, SUM(qty) qty, SUM(net_cents) net FROM sales
               WHERE qty > 0 GROUP BY item, variation"""):
        for key in (s["item"], f"{s['item']} ({s['variation']})" if s["variation"] else None):
            if key:
                agg[key.lower()][0] += s["qty"]
                agg[key.lower()][1] += s["net"]
    for key, (q, net) in agg.items():
        prices[key] = net / q if q else None

    groups = {}
    for ln in lines:
        key = (ln["kind"], ln["name"])
        grp = groups.setdefault(key, {"kind": ln["kind"], "name": ln["name"], "lines": [], "cost": 0.0,
                                      "price": prices.get(ln["name"].lower()) if ln["kind"] == "item" else None})
        grp["lines"].append(ln)
        grp["cost"] += ln["qty"] * ln["cost_per_unit_cents"]

    sold_items = sorted({k for k in agg})
    sold_names = sorted({r[0] for r in db.execute("SELECT DISTINCT item FROM sales")} |
                        {f"{r[0]} ({r[1]})" for r in db.execute(
                            "SELECT DISTINCT item, variation FROM sales WHERE variation != ''")})
    modifiers = sorted({m for (mods,) in db.execute("SELECT DISTINCT modifiers FROM sales WHERE modifiers != ''")
                        for m in split_modifiers(mods)})
    covered = {(g_["kind"], g_["name"].lower()) for g_ in groups.values()}
    missing = [r[0] for r in db.execute("SELECT DISTINCT item FROM sales WHERE qty > 0 ORDER BY item")
               if ("item", r[0].lower()) not in covered
               and not any(k == "item" and n.startswith(r[0].lower() + " (") for k, n in covered)]
    del sold_items

    return render_template(
        "recipes.html", groups=list(groups.values()), sold_names=sold_names, modifiers=modifiers,
        missing=missing,
        ingredients=db.execute("SELECT * FROM ingredients ORDER BY name COLLATE NOCASE").fetchall())


