    sold_names = sorted({r[0] for r in db.execute("SELECT DISTINCT item FROM sales")} |
                        {f"{r[0]} ({r[1]})" for r in db.execute(
                            "SELECT DISTINCT item, variation FROM sales WHERE variation != ''")})
    modifiers = sorted({m for (mods,) in db.execute("SELECT DISTINCT modifiers FROM sales WHERE modifiers != ''")
                        for m in split_modifiers(mods)})
    covered = {(g_["kind"], g_["name"].lower()) for g_ in groups.values()}
    missing = [r[0] for r in db.execute("SELECT DISTINCT item FROM sales WHERE qty > 0 ORDER BY item")
               if ("item", r[0].lower()) not in covered
               and not any(k == "item" and n.startswith(r[0].lower() + " (") for k, n in covered)]
    del sold_items

    return render_template(
        "recipes.html", groups=list(groups.values()), sold_names=sold_names, modifiers=modifiers,
        missing=missing,
        ingredients=db.execute("SELECT * FROM ingredients ORDER BY name COLLATE NOCASE").fetchall())


@app.post("/recipes/<int:line_id>/delete")
def delete_recipe_line(line_id):
    db = get_db()
    db.execute("DELETE FROM recipe_lines WHERE id = ?", (line_id,))
    db.commit()
    return redirect(url_for("recipes"))


if __name__ == "__main__":
    app.run(debug=True, port=int(os.environ.get("PORT", 5050)))

