{% extends "base.html" %}
{% block content %}
<h1>Dashboard</h1>
{% include "_range.html" %}

<section class="cards">
  <div class="card"><div class="label">Net sales</div><div class="big">{{ s.net|money }}</div>
    <div class="sub">{{ s.items|num }} items · {{ s.orders }} orders</div></div>
  <div class="card"><div class="label">Expenses</div><div class="big">{{ exp_total|money }}</div>
    <div class="sub"><a href="{{ url_for('expenses', start=start, end=end) }}">See breakdown</a></div></div>
  <div class="card {{ 'good' if profit >= 0 else 'bad' }}"><div class="label">Profit</div><div class="big">{{ profit|money }}</div>
    <div class="sub">Net sales − expenses</div></div>
  <div class="card"><div class="label">Sales tax collected</div><div class="big">{{ s.tax|money }}</div>
    <div class="sub">Owed to the state, not income</div></div>
</section>

<div class="grid2">
  <section class="panel">
    <h2>Daily net sales</h2>
    {% if daily %}
      <div class="bars">
        {% for d in daily %}
          <a class="bar" href="{{ url_for('sales', start=start, end=end, day=d.date) }}" title="{{ d.date }}: {{ d.net|money }}">
            <span style="height: {{ (d.net / max_day * 100) if d.net > 0 else 0 }}%"></span>
            <small>{{ d.date[8:] }}</small>
          </a>
        {% endfor %}
      </div>
    {% else %}
      <p class="empty">No sales in this range. <a href="{{ url_for('import_sales') }}">Import a Square export</a>.</p>
    {% endif %}
  </section>

  <section class="panel">
    <h2>Top sellers</h2>
    {% if top_items %}
    <table>
      <tr><th>Item</th><th class="r">Qty</th><th class="r">Net</th></tr>
      {% for t in top_items %}<tr><td>{{ t.item }}</td><td class="r">{{ t.qty|num }}</td><td class="r">{{ t.net|money }}</td></tr>{% endfor %}
    </table>
    {% else %}<p class="empty">Nothing sold yet in this range.</p>{% endif %}
  </section>

  <section class="panel">
    <h2>Expenses by category</h2>
    {% if exp_by_cat %}
    <table>
      {% for c in exp_by_cat %}<tr><td>{{ c.category }}</td><td class="r">{{ c.total|money }}</td></tr>{% endfor %}
    </table>
    {% else %}<p class="empty">No expenses logged in this range.</p>{% endif %}
    <p class="note">Estimated ingredient cost of drinks sold: <b>{{ ingredient_cost|money }}</b>
      {% if s.net > 0 %}({{ '%.0f' % (ingredient_cost / s.net * 100) }}% of net sales){% endif %}.
      Based on your <a href="{{ url_for('recipes') }}">recipes</a>.</p>
  </section>

  <section class="panel">
    <h2>Low stock</h2>
    {% if low_stock %}
    <table>
      {% for i in low_stock %}<tr class="warn"><td>{{ i.name }}</td><td class="r">{{ i.stock|num }} {{ i.unit }} left</td></tr>{% endfor %}
    </table>
    {% else %}<p class="empty">Everything is above its reorder level.</p>{% endif %}
  </section>
</div>
{% endblock %}

