{% extends "base.html" %}
{% block content %}
<h1>Recipes</h1>
<p class="muted">Tell Boba Books what each drink and topping uses. Imported sales then deduct ingredients from inventory, and you can see the cost of each drink.</p>

{% if missing %}
<div class="flash warn">Sold items with no recipe yet: {{ missing|join(', ') }}</div>
{% endif %}

<section class="panel">
  <h2>Add an ingredient to a recipe</h2>
  {% if ingredients %}
  <form method="post" class="form-grid">
    <label>Type
      <select name="kind">
        <option value="item">Drink / menu item</option>
        <option value="modifier">Topping / modifier</option>
      </select>
    </label>
    <label>Name (as in Square) <input name="name" list="names" required placeholder="e.g. Classic Milk Tea"></label>
    <datalist id="names">
      {% for n in sold_names %}<option value="{{ n }}">{% endfor %}
      {% for m in modifiers %}<option value="{{ m }}">{% endfor %}
    </datalist>
    <label>Ingredient
      <select name="ingredient_id" required>
        {% for i in ingredients %}<option value="{{ i.id }}">{{ i.name }} ({{ i.unit }})</option>{% endfor %}
      </select>
    </label>
    <label>Amount per drink <input name="qty" inputmode="decimal" required placeholder="e.g. 60"></label>
    <div class="wide"><button type="submit">Save</button></div>
  </form>
  <p class="note">Use <b>Item</b> for every size, or <b>Item (Large)</b> for a size-specific recipe, which takes priority.
    Toppings like "Boba" are modifiers and their ingredients are added on top of the drink's.</p>
  {% else %}
  <p class="empty">Add <a href="{{ url_for('inventory') }}">ingredients</a> first.</p>
  {% endif %}
</section>

<div class="recipe-grid">
  {% for grp in groups %}
  <section class="panel" id="r-{{ grp.kind }}-{{ grp.name }}">
    <h2>{{ grp.name }} <span class="tag">{{ 'topping' if grp.kind == 'modifier' else 'drink' }}</span></h2>
    <table>
      {% for ln in grp.lines %}
        <tr><td>{{ ln.ingredient }}</td><td class="r">{{ ln.qty|num }} {{ ln.unit }}</td>
            <td class="r muted">{{ (ln.qty * ln.cost_per_unit_cents)|money }}</td>
            <td><form method="post" action="{{ url_for('delete_recipe_line', line_id=ln.id) }}"><button class="link danger">×</button></form></td></tr>
      {% endfor %}
      <tr class="total"><td>Cost</td><td></td><td class="r">{{ grp.cost|money }}</td><td></td></tr>
      {% if grp.price %}
        <tr><td>Avg. price</td><td></td><td class="r">{{ grp.price|money }}</td><td></td></tr>
        <tr><td>Ingredient cost %</td><td></td><td class="r"><b>{{ '%.0f' % (grp.cost / grp.price * 100) }}%</b></td><td></td></tr>
      {% endif %}
    </table>
  </section>
  {% else %}
  <p class="empty">No recipes yet.</p>
  {% endfor %}
</div>
{% endblock %}

