input.content:
:root {
  --bg: #faf6f1;
  --panel: #ffffff;
  --ink: #2b211b;
  --muted: #8a7a6e;
  --line: #ece3d9;
  --brand: #7a4a2b;
  --brand-soft: #f3e6da;
  --good: #2f7d4f;
  --bad: #b23b3b;
  --warn-bg: #fff4dc;
  --warn-ink: #8a5a00;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1c1714; --panel: #26201c; --ink: #f1e9e1; --muted: #a8988b; --line: #3a312b;
    --brand: #e0a877; --brand-soft: #3a2c22; --good: #6fcf97; --bad: #ef7d7d;
    --warn-bg: #3a2f17; --warn-ink: #f2c66b;
  }
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink);
  font: 15px/1.45 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; }
a { color: var(--brand); }
h1 { font-size: 26px; margin: 0 0 16px; }
h2 { font-size: 16px; margin: 0 0 12px; }

.topbar { display: flex; align-items: center; gap: 24px; padding: 12px 24px;
  background: var(--panel); border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.brand { font-weight: 700; font-size: 18px; text-decoration: none; color: var(--ink); }
.topbar nav { display: flex; gap: 4px; flex-wrap: wrap; }
.topbar nav a { padding: 6px 12px; border-radius: 8px; text-decoration: none; color: var(--muted); }
.topbar nav a:hover { background: var(--brand-soft); color: var(--ink); }
.topbar nav a.active { background: var(--brand-soft); color: var(--brand); font-weight: 600; }

main { max-width: 1150px; margin: 0 auto; padding: 24px 16px 60px; }
.head-row { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; flex-wrap: wrap; }

.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 18px; margin-bottom: 16px; overflow-x: auto; }
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.grid2 > .panel { margin-bottom: 0; }
.grid2.narrow-first { grid-template-columns: 1fr 2fr; }
.recipe-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 16px; }
.recipe-grid > .panel { margin-bottom: 0; }
@media (max-width: 800px) { .grid2, .grid2.narrow-first { grid-template-columns: 1fr; } }

.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 16px; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 16px; }
.card .label { color: var(--muted); font-size: 13px; }
.card .big { font-size: 28px; font-weight: 700; margin: 4px 0; font-variant-numeric: tabular-nums; }
.card .sub { color: var(--muted); font-size: 13px; }
.card.good .big { color: var(--good); }
.card.bad .big { color: var(--bad); }

table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
th { text-align: left; font-weight: 600; color: var(--muted); font-size: 13px; }
th, td { padding: 7px 8px; border-bottom: 1px solid var(--line); vertical-align: top; }
tr:last-child td { border-bottom: none; }
.r { text-align: right; }
tr.total td { font-weight: 700; border-top: 2px solid var(--line); }
tr.warn td { background: var(--warn-bg); }
tr.selected td { background: var(--brand-soft); }
