"""Parse a Venmo statement CSV (venmo.com -> Statements -> Download CSV).

Venmo puts a few title lines above the real header row, so we search for the
row containing "ID", "Datetime" and "Amount (total)". Only completed incoming
payments are kept; transfers to your bank and outgoing payments are skipped.
"""

import csv
import datetime as dt
import io
import re
from decimal import Decimal, InvalidOperation


class VenmoImportError(Exception):
    pass


def parse_money(value):
    """'+ $5.50' -> 550, '- $1.00' -> -100, '' -> 0."""
    s = (value or "").strip()
    if not s:
        return 0
    negative = s.startswith("-") or (s.startswith("(") and s.endswith(")"))
    digits = re.sub(r"[^0-9.]", "", s)
    if not digits:
        return 0
    try:
        cents = int((Decimal(digits) * 100).quantize(Decimal("1")))
    except InvalidOperation:
        raise VenmoImportError(f"Couldn't read the amount {value!r}")
    return -cents if negative else cents


def parse_datetime(value):
    s = (value or "").strip()
    for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%m/%d/%Y %H:%M:%S",
                "%m/%d/%Y %H:%M", "%Y-%m-%dT%H:%M:%SZ"):
        try:
            return dt.datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise VenmoImportError(f"Couldn't read the date {value!r}")


def parse_venmo_csv(data: bytes):
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        text = data.decode("latin-1")
    all_rows = list(csv.reader(io.StringIO(text)))

    header_idx = None
    for i, row in enumerate(all_rows):
        cells = [c.strip().lower() for c in row]
        if "id" in cells and "datetime" in cells and "amount (total)" in cells:
            header_idx = i
            break
    if header_idx is None:
        raise VenmoImportError(
            "This doesn't look like a Venmo statement CSV "
            "(couldn't find the ID / Datetime / Amount (total) columns).")

    cols = {c.strip().lower(): j for j, c in enumerate(all_rows[header_idx])}

    def col(row, name):
        j = cols.get(name)
        return row[j].strip() if j is not None and j < len(row) else ""

    payments = []
    for row in all_rows[header_idx + 1:]:
        venmo_id = col(row, "id")
        if not venmo_id or not col(row, "datetime"):
            continue  # blank lines and the summary rows at the bottom
        status = col(row, "status").lower()
        if status and status not in ("complete", "completed", "issued"):
            continue
        amount = parse_money(col(row, "amount (total)"))
        if amount <= 0 or "transfer" in col(row, "type").lower():
            continue
        when = parse_datetime(col(row, "datetime"))
        payments.append({
            "venmo_id": venmo_id,
            "date": when.date().isoformat(),
            "time": when.strftime("%H:%M"),
            "from_name": col(row, "from"),
            "note": col(row, "note"),
            "amount_cents": amount,
            "fee_cents": abs(parse_money(col(row, "amount (fee)"))),
        })
    return payments

