import datetime as dt
import os
import sqlite3
from collections import defaultdict

from flask import Flask, flash, g, jsonify, redirect, render_template, request, url_for

from venmo_import import VenmoImportError, parse_venmo_csv

app = Flask(__name__)
app.config["DATABASE"] = os.environ.get("BOBA_DB", os.path.join(app.root_path, "boba.db"))
app.config["MAX_CONTENT_LENGTH"] = 20 * 1024 * 1024
app.secret_key = os.environ.get("BOBA_SECRET", "local-only")

EXPENSE_CATEGORIES = [
    "Ingredients", "Packaging", "Rent", "Utilities", "Payroll",
    "Equipment", "Card & payment fees", "Marketing", "Insurance", "Other",
]
PAYMENT_METHODS = ["Venmo", "Cash", "Card", "Other"]


# ---------- database ----------

def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(app.config["DATABASE"])
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    with app.app_context():
        with open(os.path.join(app.root_path, "schema.sql")) as f:
            get_db().executescript(f.read())


init_db()


def get_setting(db, key, default):
    row = db.execute("SELECT value FROM settings WHERE key = ?", (key,)).fetchone()
    return row[0] if row else default


def tax_settings(db):
    return (float(get_setting(db, "tax_rate", "0")),
            get_setting(db, "prices_include_tax", "1") == "1")


# ---------- helpers ----------

@app.template_filter("money")
def money(cents):
    cents = round(cents or 0)
    sign = "-" if cents < 0 else ""
    return f"{sign}${abs(cents) / 100:,.2f}"


@app.template_filter("num")
def num(value):
    value = value or 0
    return f"{value:,.0f}" if float(value).is_integer() else f"{value:,.2f}"


def today():
    return dt.date.today()


def parse_amount(value):
    """'12.50' or '$1,200' -> cents."""
    return round(parse_unit_cost(value))


def parse_unit_cost(value):
    """Per-unit costs can be fractions of a cent: '0.004' ($/ml) -> 0.4 cents."""
    s = (value or "").replace("$", "").replace(",", "").strip()
    return float(s) * 100


def split_list(value):
    return [m.strip() for m in (value or "").split(",") if m.strip()]


def date_range():
    """Read ?start=&end= from the query string; default to this month."""
    t = today()
    start = request.args.get("start") or t.replace(day=1).isoformat()
    end = request.args.get("end") or t.isoformat()
    if start > end:
        start, end = end, start
    first_this = t.replace(day=1)
    last_month_end = first_this - dt.timedelta(days=1)
    presets = {
        "Today": (t.isoformat(), t.isoformat()),
        "Last 7 days": ((t - dt.timedelta(days=6)).isoformat(), t.isoformat()),
        "This month": (first_this.isoformat(), t.isoformat()),
        "Last month": (last_month_end.replace(day=1).isoformat(), last_month_end.isoformat()),
        "This year": (t.replace(month=1, day=1).isoformat(), t.isoformat()),
    }
    return start, end, presets


def stock_levels(db):
    return db.execute(
        """
        SELECT i.*,
               COALESCE((SELECT SUM(qty) FROM stock_movements m WHERE m.ingredient_id = i.id), 0) AS stock,
               COALESCE((SELECT -SUM(qty) FROM stock_movements m
                         WHERE m.ingredient_id = i.id AND m.reason = 'sale' AND m.date >= ?), 0) AS used_30d
        FROM ingredients i ORDER BY i.name COLLATE NOCASE
        """,
        ((today() - dt.timedelta(days=29)).isoformat(),),
    ).fetchall()


def load_recipes(db):
    recipes = defaultdict(list)
    for r in db.execute("SELECT kind, name, ingredient_id, qty FROM recipe_lines"):
        recipes[(r["kind"], r["name"].lower())].append((r["ingredient_id"], r["qty"]))
    return recipes


def item_recipe(recipes, item, size):
    if size:
        lines = recipes.get(("item", f"{item} ({size})".lower()))
        if lines:
            return lines
    return recipes.get(("item", item.lower()), [])


def split_cents(total, weights):
    """Split `total` cents across `weights` proportionally, summing exactly."""
    wsum = sum(weights)
    if not wsum:
        return [0] * len(weights)
    parts = [total * w // wsum for w in weights]
    for i in range(total - sum(parts)):
        parts[i % len(parts)] += 1
    return parts


# ---------- register ----------

@app.route("/register")
def register():
    db = get_db()
    drinks = db.execute(
        "SELECT * FROM menu_items WHERE kind = 'drink' AND active = 1 ORDER BY category, sort, name").fetchall()
    toppings = db.execute(
        "SELECT * FROM menu_items WHERE kind = 'topping' AND active = 1 ORDER BY sort, name").fetchall()
    rate, inclusive = tax_settings(db)
    return render_template(
        "register.html",
        drinks=[dict(d) for d in drinks], toppings=[dict(t) for t in toppings],
        tax_rate=rate, prices_include_tax=inclusive, methods=PAYMENT_METHODS,
        today_totals=today_totals(db), today=today().isoformat())


def today_totals(db):
    rows = db.execute(
        """SELECT payment_method, COUNT(*) n, SUM(total_cents) total FROM orders
           WHERE date = ? GROUP BY payment_method""", (today().isoformat(),)).fetchall()
    return {"orders": sum(r["n"] for r in rows), "total": sum(r["total"] for r in rows),
            "by_method": {r["payment_method"]: r["total"] for r in rows}}


@app.post("/register/order")
def save_order():
    """Body: {lines: [{id, size, toppings: [id], qty}], payment_method, discount, note, date}.
    Prices are looked up from the menu here, not trusted from the browser."""
    db = get_db()
    body = request.get_json(silent=True) or {}
    method = body.get("payment_method")
    if method not in PAYMENT_METHODS:
        return jsonify(error="Pick a payment method."), 400

    menu = {r["id"]: r for r in db.execute("SELECT * FROM menu_items")}
    lines = []
    for ln in body.get("lines") or []:
        drink = menu.get(ln.get("id"))
        if not drink or drink["kind"] != "drink":
            return jsonify(error="Unknown drink, try reloading the page."), 400
        size = "Large" if ln.get("size") == "Large" and drink["large_price_cents"] is not None else ""
        price = drink["large_price_cents"] if size else drink["price_cents"]
        tops = [menu[t] for t in ln.get("toppings") or [] if t in menu and menu[t]["kind"] == "topping"]
        qty = max(1, int(ln.get("qty") or 1))
        lines.append({
            "item": drink["name"], "size": size, "qty": qty,
            "toppings": ", ".join(t["name"] for t in tops),
            "gross_cents": (price + sum(t["price_cents"] for t in tops)) * qty,
        })
    if not lines:
        return jsonify(error="The order is empty."), 400

    subtotal = sum(ln["gross_cents"] for ln in lines)
    try:
        discount = min(max(parse_amount(str(body.get("discount") or "0")), 0), subtotal)
    except ValueError:
        return jsonify(error="Discount needs to be a number."), 400
    rate, inclusive = tax_settings(db)
    after_discount = subtotal - discount
    if inclusive:
        total = after_discount
        tax = round(total - total / (1 + rate / 100))
    else:
        tax = round(after_discount * rate / 100)
        total = after_discount + tax
    net = total - tax

    date = body.get("date") or today().isoformat()
    try:
        dt.date.fromisoformat(date)
    except ValueError:
        return jsonify(error="Bad date."), 400
    now = dt.datetime.now()
    cur = db.execute(
        """INSERT INTO orders (date, time, payment_method, subtotal_cents, discount_cents,
                               tax_cents, net_cents, total_cents, note, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (date, now.strftime("%H:%M"), method, subtotal, discount, tax, net, total,
         (body.get("note") or "").strip(), now.isoformat(timespec="seconds")))
    order_id = cur.lastrowid

    recipes = load_recipes(db)
    for ln, line_net in zip(lines, split_cents(net, [ln["gross_cents"] for ln in lines])):
        lc = db.execute(
            """INSERT INTO order_lines (order_id, item, size, toppings, qty, gross_cents, net_cents)
               VALUES (?, ?, ?, ?, ?, ?, ?)""",
            (order_id, ln["item"], ln["size"], ln["toppings"], ln["qty"], ln["gross_cents"], line_net))
        usage = defaultdict(float)
        for ing_id, q in item_recipe(recipes, ln["item"], ln["size"]):
            usage[ing_id] += q * ln["qty"]
        for top in split_list(ln["toppings"]):
            for ing_id, q in recipes.get(("modifier", top.lower()), []):
                usage[ing_id] += q * ln["qty"]
        db.executemany(
            """INSERT INTO stock_movements (date, ingredient_id, qty, reason, order_line_id)
               VALUES (?, ?, ?, 'sale', ?)""",
            [(date, ing_id, -q, lc.lastrowid) for ing_id, q in usage.items()])
    db.commit()
    return jsonify(order_id=order_id, total_cents=total, payment_method=method,
                   today=today_totals(db))


# ---------- dashboard ----------

@app.route("/")
def dashboard():
    db = get_db()
    start, end, presets = date_range()
    rng = (start, end)

    s = db.execute(
        """SELECT COALESCE(SUM(total_cents),0) total, COALESCE(SUM(discount_cents),0) discounts,
                  COALESCE(SUM(net_cents),0) net, COALESCE(SUM(tax_cents),0) tax, COUNT(*) orders,
                  COALESCE((SELECT SUM(l.qty) FROM order_lines l JOIN orders o ON o.id = l.order_id
                            WHERE o.date BETWEEN ? AND ?),0) items
           FROM orders WHERE date BETWEEN ? AND ?""", rng + rng).fetchone()
    by_method = db.execute(
        """SELECT payment_method, SUM(total_cents) total, COUNT(*) n FROM orders
           WHERE date BETWEEN ? AND ? GROUP BY payment_method ORDER BY total DESC""", rng).fetchall()
    exp_total = db.execute(
        "SELECT COALESCE(SUM(amount_cents),0) FROM expenses WHERE date BETWEEN ? AND ?", rng
    ).fetchone()[0]
    exp_by_cat = db.execute(
        """SELECT category, SUM(amount_cents) total FROM expenses
           WHERE date BETWEEN ? AND ? GROUP BY category ORDER BY total DESC""", rng).fetchall()
    ingredient_cost = db.execute(
        """SELECT COALESCE(SUM(-m.qty * i.cost_per_unit_cents),0)
           FROM stock_movements m JOIN ingredients i ON i.id = m.ingredient_id
           WHERE m.reason = 'sale' AND m.date BETWEEN ? AND ?""", rng).fetchone()[0]

    daily = db.execute(
        """SELECT date, SUM(net_cents) net FROM orders
           WHERE date BETWEEN ? AND ? GROUP BY date ORDER BY date""", rng).fetchall()
    max_day = max([d["net"] for d in daily] + [1])

    top_items = db.execute(
        """SELECT l.item, SUM(l.qty) qty, SUM(l.net_cents) net
           FROM order_lines l JOIN orders o ON o.id = l.order_id
           WHERE o.date BETWEEN ? AND ? GROUP BY l.item ORDER BY qty DESC LIMIT 8""", rng).fetchall()

    low_stock = [i for i in stock_levels(db)
                 if i["reorder_level"] > 0 and i["stock"] <= i["reorder_level"]]
    rate, _ = tax_settings(db)
    has_menu = db.execute("SELECT 1 FROM menu_items LIMIT 1").fetchone() is not None

    return render_template(
        "dashboard.html", start=start, end=end, presets=presets, s=s, by_method=by_method,
        exp_total=exp_total, exp_by_cat=exp_by_cat, ingredient_cost=ingredient_cost,
        profit=s["net"] - exp_total, daily=daily, max_day=max_day,
        top_items=top_items, low_stock=low_stock, tax_rate=rate, has_menu=has_menu,
    )


# ---------- sales (orders) ----------

@app.route("/sales")
def sales():
    db = get_db()
    start, end, presets = date_range()
    days = db.execute(
        """SELECT date, COUNT(*) orders, SUM(discount_cents) discounts, SUM(net_cents) net,
                  SUM(tax_cents) tax, SUM(total_cents) total,
                  SUM(CASE WHEN payment_method = 'Venmo' THEN total_cents ELSE 0 END) venmo,
                  SUM(CASE WHEN payment_method = 'Cash' THEN total_cents ELSE 0 END) cash,
                  SUM(CASE WHEN payment_method IN ('Card', 'Other') THEN total_cents ELSE 0 END) other
           FROM orders WHERE date BETWEEN ? AND ? GROUP BY date ORDER BY date DESC""",
        (start, end)).fetchall()
    day = request.args.get("day")
    orders = []
    if day:
        orders = db.execute("SELECT * FROM orders WHERE date = ? ORDER BY time DESC, id DESC", (day,)).fetchall()
        lines = defaultdict(list)
        for ln in db.execute(
                """SELECT l.* FROM order_lines l JOIN orders o ON o.id = l.order_id
                   WHERE o.date = ? ORDER BY l.id""", (day,)):
            lines[ln["order_id"]].append(ln)
        orders = [{**dict(o), "lines": lines[o["id"]]} for o in orders]
    return render_template("sales.html", start=start, end=end, presets=presets,
                           days=days, day=day, orders=orders)


@app.post("/orders/<int:order_id>/delete")
def delete_order(order_id):
    db = get_db()
    db.execute("DELETE FROM orders WHERE id = ?", (order_id,))
    db.commit()
    flash(f"Order #{order_id} deleted, and its ingredients were put back in stock.", "ok")
    return redirect(request.referrer or url_for("sales"))


# ---------- payments / Venmo ----------

@app.route("/payments")
def payments():
    db = get_db()
    start, end, presets = date_range()
    rows = db.execute(
        """WITH d AS (
               SELECT date FROM orders WHERE date BETWEEN :s AND :e
               UNION SELECT date FROM venmo_payments WHERE date BETWEEN :s AND :e)
           SELECT d.date,
                  COALESCE((SELECT SUM(total_cents) FROM orders o WHERE o.date = d.date AND payment_method = 'Venmo'), 0) venmo_rung,
                  (SELECT SUM(amount_cents) FROM venmo_payments v WHERE v.date = d.date) venmo_received,
                  COALESCE((SELECT SUM(fee_cents) FROM venmo_payments v WHERE v.date = d.date), 0) venmo_fees,
                  COALESCE((SELECT SUM(total_cents) FROM orders o WHERE o.date = d.date AND payment_method = 'Cash'), 0) cash,
                  COALESCE((SELECT SUM(total_cents) FROM orders o WHERE o.date = d.date AND payment_method IN ('Card', 'Other')), 0) other
           FROM d ORDER BY d.date DESC""",
        {"s": start, "e": end}).fetchall()
    last_import = db.execute("SELECT MAX(date) FROM venmo_payments").fetchone()[0]
    return render_template("payments.html", start=start, end=end, presets=presets,
                           rows=rows, last_import=last_import, result=None)


@app.post("/payments/venmo-import")
def venmo_import():
    f = request.files.get("file")
    if not f or not f.filename:
        flash("Choose a Venmo statement CSV to upload.", "error")
        return redirect(url_for("payments"))
    try:
        rows = parse_venmo_csv(f.read())
    except VenmoImportError as e:
        flash(str(e), "error")
        return redirect(url_for("payments"))

    db = get_db()
    added = 0
    for p in rows:
        cur = db.execute(
            """INSERT OR IGNORE INTO venmo_payments
               (venmo_id, date, time, from_name, note, amount_cents, fee_cents)
               VALUES (:venmo_id, :date, :time, :from_name, :note, :amount_cents, :fee_cents)""", p)
        added += cur.rowcount
    # One fee expense per month, recalculated so re-imports never double count.
    months = {p["date"][:7] for p in rows}
    for m in months:
        fees, last_day = db.execute(
            "SELECT COALESCE(SUM(fee_cents),0), MAX(date) FROM venmo_payments WHERE substr(date,1,7) = ?",
            (m,)).fetchone()
        ref = f"venmo-fees:{m}"
        if fees:
            db.execute(
                """INSERT INTO expenses (date, vendor, category, description, amount_cents, source_ref)
                   VALUES (?, 'Venmo', 'Card & payment fees', ?, ?, ?)
                   ON CONFLICT (source_ref) DO UPDATE SET amount_cents = excluded.amount_cents,
                                                          date = excluded.date""",
                (last_day, f"Venmo fees for {m} (auto from import)", fees, ref))
        else:
            db.execute("DELETE FROM expenses WHERE source_ref = ?", (ref,))
    db.commit()

    dates = [p["date"] for p in rows]
    flash(f"Imported {added} new Venmo payments" +
          (f" ({min(dates)} to {max(dates)})" if dates else "") +
          (f"; {len(rows) - added} were already imported." if len(rows) - added else "."), "ok")
    if dates:
        return redirect(url_for("payments", start=min(dates), end=max(dates)))
    return redirect(url_for("payments"))


@app.route("/payments/venmo/<day>")
def venmo_day(day):
