@app.post("/inventory/add")
def add_ingredient():
    form = request.form
    db = get_db()
    try:
        cost = parse_unit_cost(form.get("cost") or "0")
        reorder = float(form.get("reorder_level") or 0)
        stock = float(form.get("stock") or 0)
    except ValueError:
        flash("Cost, stock and reorder level need to be numbers.", "error")
        return redirect(url_for("inventory"))
    try:
        cur = db.execute(
            "INSERT INTO ingredients (name, unit, cost_per_unit_cents, reorder_level) VALUES (?, ?, ?, ?)",
            (form["name"].strip(), form["unit"].strip(), cost, reorder))
    except sqlite3.IntegrityError:
        flash(f"There's already an ingredient called {form['name'].strip()!r}.", "error")
        return redirect(url_for("inventory"))
    if stock:
        db.execute(
            "INSERT INTO stock_movements (date, ingredient_id, qty, reason) VALUES (?, ?, ?, 'count')",
            (today().isoformat(), cur.lastrowid, stock))
    db.commit()
    flash("Ingredient added.", "ok")
    return redirect(url_for("inventory"))


@app.post("/inventory/<int:ingredient_id>/update")
def update_ingredient(ingredient_id):
    form = request.form
    db = get_db()
    try:
        cost = parse_unit_cost(form["cost"])
        reorder = float(form["reorder_level"] or 0)
        counted = float(form["counted"]) if form.get("counted", "").strip() else None
    except ValueError:
        flash("Cost, reorder level and count need to be numbers.", "error")
        return redirect(url_for("inventory"))
    db.execute("UPDATE ingredients SET cost_per_unit_cents = ?, reorder_level = ? WHERE id = ?",
               (cost, reorder, ingredient_id))
    if counted is not None:
        current = db.execute(
            "SELECT COALESCE(SUM(qty), 0) FROM stock_movements WHERE ingredient_id = ?",
            (ingredient_id,)).fetchone()[0]
        if counted != current:
            db.execute(
                "INSERT INTO stock_movements (date, ingredient_id, qty, reason) VALUES (?, ?, ?, 'count')",
                (today().isoformat(), ingredient_id, counted - current))
    db.commit()
    flash("Ingredient updated.", "ok")
    return redirect(url_for("inventory"))


@app.post("/inventory/<int:ingredient_id>/delete")
def delete_ingredient(ingredient_id):
