# ---------- dashboard ----------

@app.route("/")
def dashboard():
    db = get_db()
    start, end, presets = date_range()
    rng = (start, end)

    s = db.execute(
        """SELECT COALESCE(SUM(total_cents),0) total, COALESCE(SUM(discount_cents),0) discounts,
                  COALESCE(SUM(net_cents),0) net, COALESCE(SUM(tax_cents),0) tax, COUNT(*) orders,
                  COALESCE((SELECT SUM(l.qty) FROM order_lines l JOIN orders o ON o.id = l.order_id
                            WHERE o.date BETWEEN ? AND ?),0) items
           FROM orders WHERE date BETWEEN ? AND ?""", rng + rng).fetchone()
    by_method = db.execute(
        """SELECT payment_method, SUM(total_cents) total, COUNT(*) n FROM orders
           WHERE date BETWEEN ? AND ? GROUP BY payment_method ORDER BY total DESC""", rng).fetchall()
    exp_total = db.execute(
        "SELECT COALESCE(SUM(amount_cents),0) FROM expenses WHERE date BETWEEN ? AND ?", rng
    ).fetchone()[0]
    exp_by_cat = db.execute(
        """SELECT category, SUM(amount_cents) total FROM expenses
           WHERE date BETWEEN ? AND ? GROUP BY category ORDER BY total DESC""", rng).fetchall()
    ingredient_cost = db.execute(
        """SELECT COALESCE(SUM(-m.qty * i.cost_per_unit_cents),0)
           FROM stock_movements m JOIN ingredients i ON i.id = m.ingredient_id
           WHERE m.reason = 'sale' AND m.date BETWEEN ? AND ?""", rng).fetchone()[0]

    daily = db.execute(
        """SELECT date, SUM(net_cents) net FROM orders
           WHERE date BETWEEN ? AND ? GROUP BY date ORDER BY date""", rng).fetchall()
    max_day = max([d["net"] for d in daily] + [1])

    top_items = db.execute(
        """SELECT l.item, SUM(l.qty) qty, SUM(l.net_cents) net
           FROM order_lines l JOIN orders o ON o.id = l.order_id
           WHERE o.date BETWEEN ? AND ? GROUP BY l.item ORDER BY qty DESC LIMIT 8""", rng).fetchall()

    low_stock = [i for i in stock_levels(db)
                 if i["reorder_level"] > 0 and i["stock"] <= i["reorder_level"]]
    rate, _ = tax_settings(db)
    has_menu = db.execute("SELECT 1 FROM menu_items LIMIT 1").fetchone() is not None

    return render_template(
        "dashboard.html", start=start, end=end, presets=presets, s=s, by_method=by_method,
        exp_total=exp_total, exp_by_cat=exp_by_cat, ingredient_cost=ingredient_cost,
        profit=s["net"] - exp_total, daily=daily, max_day=max_day,
        top_items=top_items, low_stock=low_stock, tax_rate=rate, has_menu=has_menu,
    )


