# ---------- expenses ----------

@app.route("/expenses", methods=["GET", "POST"])
def expenses():
    db = get_db()
    if request.method == "POST":
        form = request.form
        try:
            amount = parse_amount(form["amount"])
            ing_id = int(form["ingredient_id"]) if form.get("ingredient_id") else None
            ing_qty = float(form["ingredient_qty"]) if form.get("ingredient_qty") else None
        except ValueError:
            flash("Amount and quantity need to be numbers.", "error")
            return redirect(url_for("expenses"))
        if ing_id and not ing_qty:
            flash("Enter how much of the ingredient you bought.", "error")
            return redirect(url_for("expenses"))

        cur = db.execute(
            """INSERT INTO expenses (date, vendor, category, description, amount_cents)
               VALUES (?, ?, ?, ?, ?)""",
            (form["date"], form.get("vendor", "").strip(), form["category"],
             form.get("description", "").strip(), amount))
        if ing_id and ing_qty:
            db.execute(
                """INSERT INTO stock_movements (date, ingredient_id, qty, reason, expense_id)
                   VALUES (?, ?, ?, 'purchase', ?)""",
                (form["date"], ing_id, ing_qty, cur.lastrowid))
            # Latest purchase price becomes the ingredient's cost.
            db.execute("UPDATE ingredients SET cost_per_unit_cents = ? WHERE id = ?",
                       (amount / ing_qty, ing_id))
        db.commit()
        flash("Expense saved.", "ok")
        return redirect(url_for("expenses", start=request.args.get("start"),
                                end=request.args.get("end")))

    start, end, presets = date_range()
    rows = db.execute(
        """SELECT e.*, i.name ingredient, i.unit, m.qty ingredient_qty
           FROM expenses e
           LEFT JOIN stock_movements m ON m.expense_id = e.id
           LEFT JOIN ingredients i ON i.id = m.ingredient_id
           WHERE e.date BETWEEN ? AND ? ORDER BY e.date DESC, e.id DESC""",
        (start, end)).fetchall()
    by_cat = db.execute(
        """SELECT category, SUM(amount_cents) total FROM expenses
           WHERE date BETWEEN ? AND ? GROUP BY category ORDER BY total DESC""",
        (start, end)).fetchall()
    ingredients = db.execute("SELECT * FROM ingredients ORDER BY name COLLATE NOCASE").fetchall()
    vendors = [r[0] for r in db.execute(
        "SELECT DISTINCT vendor FROM expenses WHERE vendor != '' ORDER BY vendor")]
    return render_template(
        "expenses.html", start=start, end=end, presets=presets, rows=rows, by_cat=by_cat,
        total=sum(r["total"] for r in by_cat), categories=EXPENSE_CATEGORIES,
        ingredients=ingredients, vendors=vendors, today=today().isoformat())


