@app.post("/inventory/<int:ingredient_id>/update")
def update_ingredient(ingredient_id):
    form = request.form
    db = get_db()
    try:
        cost = parse_unit_cost(form["cost"])
        reorder = float(form["reorder_level"] or 0)
        counted = float(form["counted"]) if form.get("counted", "").strip() else None
    except ValueError:
        flash("Cost, reorder level and count need to be numbers.", "error")
        return redirect(url_for("inventory"))
    db.execute("UPDATE ingredients SET cost_per_unit_cents = ?, reorder_level = ? WHERE id = ?",
               (cost, reorder, ingredient_id))
    if counted is not None:
        current = db.execute(
            "SELECT COALESCE(SUM(qty), 0) FROM stock_movements WHERE ingredient_id = ?",
            (ingredient_id,)).fetchone()[0]
        if counted != current:
            db.execute(
                "INSERT INTO stock_movements (date, ingredient_id, qty, reason) VALUES (?, ?, ?, 'count')",
                (today().isoformat(), ingredient_id, counted - current))
    db.commit()
    flash("Ingredient updated.", "ok")
    return redirect(url_for("inventory"))


