            """INSERT INTO expenses (date, vendor, category, description, amount_cents)
               VALUES (?, ?, ?, ?, ?)""",
            (form["date"], form.get("vendor", "").strip(), form["category"],
             form.get("description", "").strip(), amount))
        if ing_id and ing_qty:
            db.execute(
                """INSERT INTO stock_movements (date, ingredient_id, qty, reason, expense_id)
                   VALUES (?, ?, ?, 'purchase', ?)""",
                (form["date"], ing_id, ing_qty, cur.lastrowid))
            # Latest purchase price becomes the ingredient's cost.
            db.execute("UPDATE ingredients SET cost_per_unit_cents = ? WHERE id = ?",
                       (amount / ing_qty, ing_id))
