@app.route("/recipes", methods=["GET", "POST"])
def recipes():
    db = get_db()
    if request.method == "POST":
        form = request.form
        try:
            qty = float(form["qty"])
        except ValueError:
            flash("Amount needs to be a number.", "error")
            return redirect(url_for("recipes"))
        db.execute(
            """INSERT INTO recipe_lines (kind, name, ingredient_id, qty) VALUES (?, ?, ?, ?)
               ON CONFLICT (kind, name, ingredient_id) DO UPDATE SET qty = excluded.qty""",
            (form["kind"], form["name"].strip(), int(form["ingredient_id"]), qty))
        db.commit()
        flash("Recipe saved.", "ok")
        return redirect(url_for("recipes") + "#r-" + form["kind"] + "-" + form["name"].strip())

    lines = db.execute(
        """SELECT r.*, i.name ingredient, i.unit, i.cost_per_unit_cents
           FROM recipe_lines r JOIN ingredients i ON i.id = r.ingredient_id
           ORDER BY r.kind, r.name COLLATE NOCASE, i.name COLLATE NOCASE""").fetchall()

    # Menu price per drink/topping, keyed the same way recipes are matched.
    menu_items = db.execute("SELECT * FROM menu_items").fetchall()
    prices = {}
    drink_names, topping_names = [], []
    for m in menu_items:
        prices[m["name"].lower()] = m["price_cents"]
        if m["kind"] == "topping":
            topping_names.append(m["name"])
            continue
        drink_names.append(m["name"])
        if m["large_price_cents"] is not None:
            prices[f"{m['name']} (Large)".lower()] = m["large_price_cents"]
            drink_names.append(f"{m['name']} (Large)")
    rate, inclusive = tax_settings(db)

    groups = {}
    for ln in lines:
        price = prices.get(ln["name"].lower())
        if price and inclusive:
            price = price / (1 + rate / 100)  # compare cost against revenue, not tax
        grp = groups.setdefault((ln["kind"], ln["name"]), {
            "kind": ln["kind"], "name": ln["name"], "lines": [], "cost": 0.0, "price": price})
        grp["lines"].append(ln)
        grp["cost"] += ln["qty"] * ln["cost_per_unit_cents"]

    covered = {(g_["kind"], g_["name"].lower()) for g_ in groups.values()}
    missing = [m["name"] for m in menu_items if m["active"] and (
        "item" if m["kind"] == "drink" else "modifier", m["name"].lower()) not in covered]

    return render_template(
        "recipes.html", groups=list(groups.values()), drink_names=sorted(drink_names),
        topping_names=sorted(topping_names), missing=missing,
        ingredients=db.execute("SELECT * FROM ingredients ORDER BY name COLLATE NOCASE").fetchall())


