    db = get_db()
    db.execute("DELETE FROM recipe_lines WHERE id = ?", (line_id,))
    db.commit()
    return redirect(url_for("recipes"))


if __name__ == "__main__":
    # HOST=0.0.0.0 lets an iPad/phone on the same Wi-Fi open the register.
    # The debugger stays off then, since it would let anyone on the network run code.
    host = os.environ.get("HOST", "127.0.0.1")
    app.run(host=host, port=int(os.environ.get("PORT", 5050)),
            debug=host in ("127.0.0.1", "localhost") and os.environ.get("BOBA_DEBUG") == "1")

