          {% endif %}
        </div>
      </div>
    {% endfor %}
    </div>
  </section>

  <section class="reg-order panel">
    <div class="order-head"><h2>Current order</h2><button type="button" class="link" id="clear">Clear</button></div>
    <ul id="lines" class="order-lines"></ul>
    <p id="empty" class="empty">Tap a drink to start.</p>

    {% if toppings %}
    <div id="topping-box" hidden>
      <div class="muted small">Toppings for <b id="sel-name"></b></div>
      <div class="chips">
        {% for t in toppings %}<button type="button" class="chip" data-top="{{ t.id }}">{{ t.name }} +{{ t.price_cents|money }}</button>{% endfor %}
      </div>
    </div>
    {% endif %}

    <details class="more">
      <summary>Discount, note, or a different date</summary>
      <label>Discount ($) <input id="discount" inputmode="decimal" placeholder="0.00"></label>
      <label>Note <input id="note" placeholder="optional, e.g. Venmo name"></label>
      <label>Date <input id="date" type="date" value="{{ today }}"></label>
    </details>

    <table class="totals">
      <tr><td>Subtotal</td><td class="r" id="t-sub"></td></tr>
      <tr id="row-disc" hidden><td>Discount</td><td class="r" id="t-disc"></td></tr>
      <tr><td>Tax {{ '%g' % tax_rate }}%{% if prices_include_tax %} (included){% endif %}</td><td class="r" id="t-tax"></td></tr>
      <tr class="grand"><td>Total</td><td class="r" id="t-total"></td></tr>
    </table>

    <div class="pay">
      {% for m in methods %}<button type="button" class="pay-{{ m|lower }}" data-pay="{{ m }}" disabled>{{ m }}</button>{% endfor %}
    </div>
    <div id="toast" class="toast" hidden></div>
  </section>
</div>

<script>
const DRINKS = Object.fromEntries({{ drinks|tojson }}.map(d => [d.id, d]));
const TOPPINGS = Object.fromEntries({{ toppings|tojson }}.map(t => [t.id, t]));
const TAX_RATE = {{ tax_rate }}, INCLUSIVE = {{ 'true' if prices_include_tax else 'false' }};
let today = {{ today_totals|tojson }};
let lines = [], selected = -1;

const $ = id => document.getElementById(id);
const fmt = c => (c < 0 ? "-$" : "$") + (Math.abs(c) / 100).toFixed(2);
const esc = s => s.replace(/[&<>"]/g, ch => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}[ch]));

function unitPrice(ln) {
  const d = DRINKS[ln.id];
  const base = ln.size === "Large" ? d.large_price_cents : d.price_cents;
  return base + ln.toppings.reduce((s, t) => s + TOPPINGS[t].price_cents, 0);
}

function totals() {
  const sub = lines.reduce((s, ln) => s + unitPrice(ln) * ln.qty, 0);
  const disc = Math.min(Math.max(Math.round(parseFloat($("discount").value || "0") * 100) || 0, 0), sub);
  const after = sub - disc;
  let tax, total;
  if (INCLUSIVE) { total = after; tax = Math.round(total - total / (1 + TAX_RATE / 100)); }
  else { tax = Math.round(after * TAX_RATE / 100); total = after + tax; }
  return {sub, disc, tax, total};
}

function render() {
  $("lines").innerHTML = lines.map((ln, i) => {
    const d = DRINKS[ln.id];
    const tops = ln.toppings.map(t => TOPPINGS[t].name).join(", ");
    return `<li class="${i === selected ? "sel" : ""}" data-sel="${i}">
      <div class="ln-main"><b>${esc(d.name)}</b>${ln.size ? ` <span class="tag">L</span>` : ""}
        ${tops ? `<div class="muted small">+ ${esc(tops)}</div>` : ""}</div>
      <div class="qty"><button type="button" data-dec="${i}">−</button><span>${ln.qty}</span><button type="button" data-inc="${i}">+</button></div>
      <div class="ln-price">${fmt(unitPrice(ln) * ln.qty)}</div>
      <button type="button" class="link danger" data-del="${i}" aria-label="Remove">×</button></li>`;
  }).join("");
  $("empty").hidden = lines.length > 0;

  const box = $("topping-box");
  if (box) {
    box.hidden = selected < 0;
    if (selected >= 0) {
      $("sel-name").textContent = DRINKS[lines[selected].id].name;
      box.querySelectorAll("[data-top]").forEach(b =>
        b.classList.toggle("on", lines[selected].toppings.includes(+b.dataset.top)));
    }
  }

  const t = totals();
  $("t-sub").textContent = fmt(t.sub);
  $("row-disc").hidden = !t.disc;
  $("t-disc").textContent = fmt(-t.disc);
  $("t-tax").textContent = fmt(t.tax);
  $("t-total").textContent = fmt(t.total);
  document.querySelectorAll("[data-pay]").forEach(b => b.disabled = !lines.length);

  const bm = Object.entries(today.by_method || {}).map(([m, c]) => `${m} ${fmt(c)}`).join(" · ");
  $("today-strip").innerHTML = `Today: <b>${today.orders}</b> orders · <b>${fmt(today.total || 0)}</b>${bm ? ` <span class="muted">(${bm})</span>` : ""}`;
}

document.addEventListener("click", async e => {
  const b = e.target.closest("button, li[data-sel]");
  if (!b) return;
  const ds = b.dataset;
  if (ds.add) { lines.push({id: +ds.add, size: ds.size, toppings: [], qty: 1}); selected = lines.length - 1; }
  else if (ds.top) {
    const tops = lines[selected].toppings, id = +ds.top;
    const k = tops.indexOf(id); k >= 0 ? tops.splice(k, 1) : tops.push(id);
  }
  else if (ds.inc) lines[+ds.inc].qty++;
  else if (ds.dec) { if (lines[+ds.dec].qty > 1) lines[+ds.dec].qty--; }
  else if (ds.del) { lines.splice(+ds.del, 1); selected = Math.min(selected, lines.length - 1); }
  else if (ds.sel !== undefined) selected = +ds.sel;
  else if (b.id === "clear") { lines = []; selected = -1; }
  else if (ds.pay) return pay(ds.pay, b);
  else return;
  render();
});
$("discount").addEventListener("input", render);

async function pay(method, btn) {
  document.querySelectorAll("[data-pay]").forEach(b => b.disabled = true);
  try {
    const res = await fetch("{{ url_for('save_order') }}", {
      method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({lines, payment_method: method, discount: $("discount").value,
                            note: $("note").value, date: $("date").value}),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || "Couldn't save the order.");
    today = data.today;
    lines = []; selected = -1;
    $("discount").value = ""; $("note").value = "";
    showToast(`Order #${data.order_id} saved · ${fmt(data.total_cents)} ${data.payment_method}`, "ok");
  } catch (err) {
    showToast(err.message, "error");
  }
  render();
}

let toastTimer;
function showToast(msg, kind) {
  const t = $("toast");
  t.textContent = msg; t.className = "toast " + kind; t.hidden = false;
  clearTimeout(toastTimer); toastTimer = setTimeout(() => t.hidden = true, 4000);
}

render();
</script>
{% endif %}
{% endblock %}

