        <td class="r">{{ d.venmo|money }}</td><td class="r">{{ d.cash|money }}</td><td class="r">{{ d.other|money }}</td>
        <td class="r">{{ d.total|money }}</td><td class="r">{{ d.tax|money }}</td>
        <td class="r"><b>{{ d.net|money }}</b></td>
      </tr>
