          {% endfor %}
          {% if o.discount_cents %}<div class="muted small">Discount {{ o.discount_cents|money }}</div>{% endif %}
          {% if o.note %}<div class="muted small">“{{ o.note }}”</div>{% endif %}
        </td>
        <td><span class="method m-{{ o.payment_method|lower }}">{{ o.payment_method }}</span></td>
        <td class="r">{{ o.total_cents|money }}</td>
