input.command:
cat >> static/style.css <<'EOF'

/* ---------- shared bits ---------- */
.small { font-size: 12px; }
.ok-text { color: var(--good); font-weight: 600; }
.bad-text { color: var(--bad); font-weight: 600; }
.method { display: inline-block; font-size: 12px; font-weight: 600; padding: 2px 8px; border-radius: 6px; background: var(--brand-soft); }
.m-venmo { background: #e3f0fb; color: #1b6fb5; }
.m-cash { background: #e3f4e8; color: #2f7d4f; }
@media (prefers-color-scheme: dark) { .m-venmo { background: #1d3346; color: #8cc4f2; } .m-cash { background: #1d3a27; color: #8fd8a8; } }
label.check { flex-direction: row !important; align-items: center; gap: 6px; color: var(--ink) !important; }
tr.inactive td { opacity: .5; }
.grid2.narrow-last { grid-template-columns: 2fr 1fr; }
@media (max-width: 800px) { .grid2.narrow-last { grid-template-columns: 1fr; } }
.menu-table input { width: 80px; }

/* ---------- register ---------- */
.register-page main { max-width: 1400px; }
.reg { display: grid; grid-template-columns: 1fr 380px; gap: 16px; align-items: start; }
.today-strip { font-size: 14px; margin-bottom: 8px; }
.reg-cat { font-size: 13px; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin: 16px 0 8px; }
.drink-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 10px; }
.drink { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 12px; display: flex; flex-direction: column; gap: 10px; }
.drink-name { font-weight: 700; font-size: 16px; line-height: 1.2; min-height: 2.4em; }
.drink-sizes { display: flex; gap: 6px; }
.drink-sizes button { flex: 1; padding: 12px 6px; font-size: 15px; background: var(--brand-soft); color: var(--brand); }
.drink-sizes button:active { transform: scale(.97); }

.reg-order { position: sticky; top: 12px; margin: 0; }
.order-head { display: flex; justify-content: space-between; align-items: baseline; }
.order-lines { list-style: none; margin: 0 0 10px; padding: 0; max-height: 40vh; overflow-y: auto; }
.order-lines li { display: grid; grid-template-columns: 1fr auto auto auto; gap: 8px; align-items: center;
  padding: 8px; border-radius: 8px; border: 2px solid transparent; cursor: pointer; }
.order-lines li.sel { border-color: var(--brand); background: var(--brand-soft); }
.qty { display: flex; align-items: center; gap: 6px; }
.qty button { width: 30px; height: 30px; padding: 0; background: var(--bg); color: var(--ink); border: 1px solid var(--line); }
.ln-price { font-variant-numeric: tabular-nums; min-width: 56px; text-align: right; }
.order-lines .link { font-size: 20px; padding: 0 4px; }

.chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 6px 0 12px; }
.chip { background: var(--bg); color: var(--ink); border: 1px solid var(--line); font-weight: 500; padding: 8px 12px; border-radius: 99px; }
.chip.on { background: var(--brand); color: var(--panel); border-color: var(--brand); }

.more { margin: 6px 0 10px; font-size: 14px; }
.more summary { color: var(--muted); cursor: pointer; }
.more label { display: flex; justify-content: space-between; align-items: center; gap: 8px; margin-top: 8px; color: var(--muted); }
.more input { width: 60%; }

.totals td { border: none; padding: 3px 0; }
.totals .grand td { font-size: 24px; font-weight: 800; padding-top: 8px; }
.pay { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px; }
.pay button { padding: 16px; font-size: 18px; }
.pay button:disabled { opacity: .35; cursor: default; filter: none; }
.pay .pay-venmo { background: #1b6fb5; }
.pay .pay-cash { background: #2f7d4f; }
.pay .pay-card, .pay .pay-other { background: var(--brand); }
.toast { margin-top: 12px; padding: 10px 12px; border-radius: 8px; font-weight: 600; }
.toast.ok { background: #e3f4e8; color: #2f7d4f; }
.toast.error { background: #fde8e8; color: var(--bad); }

@media (max-width: 860px) {
  .reg { grid-template-columns: 1fr; }
  .reg-order { position: static; }
  .drink-grid { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); }
}
EOF

