      <div class="checkout-total">Total <b id="c-total"></b></div>
      <div class="pay">
        {% for m in methods %}<button type="button" class="pay-{{ m|lower }}" data-pay="{{ m }}" disabled>{{ m }}</button>{% endfor %}
      </div>
      <div id="toast" class="toast" hidden></div>
    </div>'''
assert old in s; s=s.replace(old,new)
s=s.replace('''  $("t-total").textContent = fmt(t.total);''','''  $("t-total").textContent = $("c-total").textContent = fmt(t.total);''')
